 todayFieldSnapshot: {
 date: 'Sep 9, 2026 (Wednesday — EHS headcount board 219; daily report crew basis 190)',
 total: 219,
 rows: [
  { contractor: 'UNITED', people: 83, category: 'pile', note: '<strong>65 mechanical + 18 electricians on the report. The whole mechanical crew racked Zone D (35 rows at 50%, snapshot) — and installed ZERO modules, the first zero-module day since Aug 31. The LV crew filed 201 harness lines (565 strings) + 139 supports at PS19 — a number to verify before it is relied on.</strong> It still states it will not work G5/G7 until the racking is ready. Zone D racking is ECCS scope on the division — confirm.' },
  { contractor: 'ECCS', people: 65, category: 'tracker', note: '<strong>32 mechanical + 32 electrical. Mechanical: 41 rows completed to 100% in Zone G — absorbed into the held G figure (ruling needed). Electrical: 59 harness lines, the first 12 LBD terminations (boxes 101, 102, 105), 9 cables tensioned, 86 brackets at E20 — no cable footage.</strong> Line 1 order stands: closed before Sep 15 — INV-1/INV-2 trenches closed, INV-3 closing; the cabinet terminations are the open item. Zone E tracker remediation still not reported as started.' },
  { contractor: 'GREENSOL', people: 37, category: 'epc', note: '<strong>37 on the board; self-perform 10: 37 harness lines (INV-12 36, INV-11 1) — 8 INV-12 rows have no modules to harness.</strong> INV-11 closed on LV Sep 7; the crew is coordinated to enter Line 1 to help close inverters.' },
  { contractor: 'AB POWER', people: 13, category: 'electrical', note: '<strong>Report: 17 on the substation + 4 on MV terminations — ZERO terminations for a sixth day; the crew prepared the Line 2 inverter cables (goal was 12) and completed none. Cumulative 45 of 264, deficit 87.</strong> No SE percentage on the Sep 9 report (61.4% on Sep 8). The Sep 8 first-aid case came off this front; classification still not reported.' },
  { contractor: 'ITS', people: 8, category: 'civil', note: 'Back on site after four days absent — 5 on cleanup behind the substation + 3 on rig maintenance. No plow segment (38 of 46 for a twenty-sixth working day), no bore; the plan’s easement pulls all sit here.' },
  { contractor: 'BRUMONT · TOPLAND · HI TECH · ECS', people: 13, category: 'module', note: 'Brumont 1 — no module production. Topland 3 — laydown area FINISHED; junction-box distribution done, installation still to start (the report’s critical point). Hi Tech 4 (SE support), ECS 2, Roveri security 1. <strong>Workforce and Latnovva absent.</strong>' }
 ],
 note: 'Source: <strong>Sep 9 EHS headcount board (Bethany Valdez)</strong> — United 83, ECCS 65, GreenSol 37, AB Power 13, ITS 8, Hi Tech 4, Topland 3, ECS 2, Roveri 1, Brumont 1 = 219 — and the <strong>Sep 9 daily executive report</strong> (190 on the crew basis). '
 + '<strong>The read: the site produced its best harness day (297) and its first LBD terminations, and the racking contractor finally completed rows again (41, in Zone G) — but the module front went to zero because the only module crew was racking Zone D, and the MV termination crew completed nothing for a sixth day with three Line 1 stations ready.</strong>'
 },
